  if(v==='CREATE_NEW')return 1;if(v==='CREATE_ALWAYS')return 2;if(v==='OPEN_EXISTING')return 3;if(v==='OPEN_ALWAYS')return 4;if(v==='TRUNCATE_EXISTING')return 5;
  return 3;
